class User {
  constructor(public name: string, private room: ChatRoom) {}
  send(message: string) { this.room.send(this, message); }
  receive(sender: User, message: string) { console.log(`${this.name} received from ${sender.name}: ${message}`); }
}
class ChatRoom {
  private users: User[] = [];
  register(u: User) { this.users.push(u); }
  send(sender: User, message: string) { this.users.filter(u => u !== sender).forEach(u => u.receive(sender, message)); }
}

