class Coordinator {
  private peers = new Map<string, Peer>();
  register(p: Peer) { this.peers.set(p.id, p); }
  send(senderId: string, recipientId: string, msg: string) { this.peers.get(recipientId)?.receive(senderId, msg); }
}
class Peer { constructor(public id: string, private coord: Coordinator) {}
  send(to: string, msg: string) { this.coord.send(this.id, to, msg); }
  receive(from: string, msg: string) { /* handle */ }
}

